initJs:
function(container, apiUrl, tables) {
  let salesChart, orderChart, weatherChart;
  let currentStoreId = '';
  let currentPeriod = 30;

  // テーブルインデックスの定義
  const TABLE_STORES = 1;
  const TABLE_PRODUCTS = 2;
  const TABLE_SALES = 3;
  const TABLE_WEATHER = 4;
  const TABLE_EVENTS = 5;
  const TABLE_PREDICTIONS = 7;
  const TABLE_ORDERS = 8;

  // 店舗選択の初期化
  function initStoreSelect() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables[TABLE_STORES]?.records || [];

    stores.forEach(store => {
      if (store.有効フラグ) {
        const option = document.createElement('option');
        option.value = store.店舗ID;
        option.textContent = store.店舗名;
        storeSelect.appendChild(option);
      }
    });
  }

  // KPI計算と表示
  function updateKPIs() {
    const salesData = tables[TABLE_SALES]?.records || [];
    const ordersData = tables[TABLE_ORDERS]?.records || [];
    const predictionsData = tables[TABLE_PREDICTIONS]?.records || [];

    const now = new Date();
    const currentMonth = now.getFullYear() + '-' + String(now.getMonth() + 1).padStart(2, '0');
    const lastMonth = now.getFullYear() + '-' + String(now.getMonth()).padStart(2, '0');

    // 今月の売上実績
    const currentSales = salesData
      .filter(s => s.売上日?.startsWith(currentMonth) && (!currentStoreId || s.店舗ID === currentStoreId))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const lastSales = salesData
      .filter(s => s.売上日?.startsWith(lastMonth) && (!currentStoreId || s.店舗ID === currentStoreId))
      .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

    const salesChange = lastSales > 0 ? ((currentSales - lastSales) / lastSales * 100).toFixed(1) : 0;

    container.querySelector('#sales-amount').textContent = `¥${currentSales.toLocaleString()}`;
    container.querySelector('#sales-change').textContent = `前月比 ${salesChange > 0 ? '+' : ''}${salesChange}%`;

    // 需要予測精度
    const accuracyData = predictionsData.filter(p => p.実績数量 && p.予測数量);
    let avgAccuracy = 0;
    if (accuracyData.length > 0) {
      const totalAccuracy = accuracyData.reduce((sum, p) => {
        const accuracy = 100 - Math.abs(p.実績数量 - p.予測数量) / p.実績数量 * 100;
        return sum + Math.max(0, accuracy);
      }, 0);
      avgAccuracy = (totalAccuracy / accuracyData.length).toFixed(1);
    }

    container.querySelector('#prediction-accuracy').textContent = `${avgAccuracy}%`;

    // 発注件数
    const orderCount = ordersData.filter(o => !currentStoreId || o.店舗ID === currentStoreId).length;
    const processingCount = ordersData.filter(o => 
      (!currentStoreId || o.店舗ID === currentStoreId) && 
      o.発注ステータス === '発注済'
    ).length;

    container.querySelector('#order-count').textContent = `${orderCount}件`;
    container.querySelector('#order-status').textContent = `処理中: ${processingCount}件`;

    // 在庫アラート（仮想的な計算）
    const alertCount = Math.floor(Math.random() * 5) + 1;
    container.querySelector('#alert-count').textContent = `${alertCount}件`;
  }

  // 売上トレンドグラフ
  function renderSalesTrend() {
    const ctx = container.querySelector('#sales-trend-chart').getContext('2d');
    const salesData = tables[TABLE_SALES]?.records || [];

    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(endDate.getDate() - currentPeriod);

    const dailySales = {};
    for (let d = new Date(startDate); d <= endDate; d.setDate(d.getDate() + 1)) {
      const dateStr = d.toISOString().split('T')[0];
      dailySales[dateStr] = 0;
    }

    salesData
      .filter(s => {
        const saleDate = s.売上日?.split('T')[0];
        return saleDate >= startDate.toISOString().split('T')[0] && 
               saleDate <= endDate.toISOString().split('T')[0] &&
               (!currentStoreId || s.店舗ID === currentStoreId);
      })
      .forEach(s => {
        const dateStr = s.売上日?.split('T')[0];
        if (dailySales.hasOwnProperty(dateStr)) {
          dailySales[dateStr] += s.売上金額 || 0;
        }
      });

    if (salesChart) salesChart.destroy();

    salesChart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: Object.keys(dailySales).map(d => new Date(d).toLocaleDateString()),
        datasets: [{
          label: '売上金額',
          data: Object.values(dailySales),
          borderColor: '#4f46e5',
          backgroundColor: 'rgba(79, 70, 229, 0.1)',
          tension: 0.4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // 商品別売上ランキング
  function renderProductRanking() {
    const salesData = tables[TABLE_SALES]?.records || [];
    const productsData = tables[TABLE_PRODUCTS]?.records || [];

    const productSales = {};
    salesData
      .filter(s => !currentStoreId || s.店舗ID === currentStoreId)
      .forEach(s => {
        if (!productSales[s.商品ID]) {
          productSales[s.商品ID] = 0;
        }
        productSales[s.商品ID] += s.売上金額 || 0;
      });

    const ranking = Object.entries(productSales)
      .sort(([,a], [,b]) => b - a)
      .slice(0, 10)
      .map(([productId, amount], index) => {
        const product = productsData.find(p => p.商品ID === productId);
        return {
          rank: index + 1,
          name: product?.商品名 || '不明な商品',
          amount: amount
        };
      });

    const rankingHtml = ranking.length > 0 ? 
      ranking.map(item => `
        <div class="ranking-item">
          <span class="ranking-rank">${item.rank}</span>
          <span class="ranking-name">${item.name}</span>
          <span class="ranking-amount">¥${item.amount.toLocaleString()}</span>
        </div>
      `).join('') :
      '<div class="loading">データがありません</div>';

    container.querySelector('#product-ranking').innerHTML = rankingHtml;
  }

  // 発注状況チャート
  function renderOrderStatus() {
    const ctx = container.querySelector('#order-status-chart').getContext('2d');
    const ordersData = tables[TABLE_ORDERS]?.records || [];

    const statusCount = {};
    ordersData
      .filter(o => !currentStoreId || o.店舗ID === currentStoreId)
      .forEach(o => {
        const status = o.発注ステータス || '不明';
        statusCount[status] = (statusCount[status] || 0) + 1;
      });

    if (orderChart) orderChart.destroy();

    orderChart = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: Object.keys(statusCount),
        datasets: [{
          data: Object.values(statusCount),
          backgroundColor: [
            '#4f46e5',
            '#06b6d4',
            '#10b981',
            '#f59e0b',
            '#ef4444'
          ]
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false
      }
    });
  }

  // 天候影響分析チャート
  function renderWeatherImpact() {
    const ctx = container.querySelector('#weather-impact-chart').getContext('2d');
    const weatherData = tables[TABLE_WEATHER]?.records || [];
    const salesData = tables[TABLE_SALES]?.records || [];

    const weatherSales = {};
    weatherData.forEach(w => {
      const dateStr = w.観測日?.split('T')[0];
      const daySales = salesData
        .filter(s => s.売上日?.split('T')[0] === dateStr && (!currentStoreId || s.店舗ID === currentStoreId))
        .reduce((sum, s) => sum + (s.売上金額 || 0), 0);

      if (daySales > 0 && w.天気) {
        if (!weatherSales[w.天気]) {
          weatherSales[w.天気] = [];
        }
        weatherSales[w.天気].push(daySales);
      }
    });

    const avgWeatherSales = {};
    Object.keys(weatherSales).forEach(weather => {
      const sales = weatherSales[weather];
      avgWeatherSales[weather] = sales.reduce((sum, s) => sum + s, 0) / sales.length;
    });

    if (weatherChart) weatherChart.destroy();

    weatherChart = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: Object.keys(avgWeatherSales),
        datasets: [{
          label: '平均売上金額',
          data: Object.values(avgWeatherSales),
          backgroundColor: 'rgba(79, 70, 229, 0.6)',
          borderColor: '#4f46e5',
          borderWidth: 1
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          y: {
            beginAtZero: true,
            ticks: {
              callback: function(value) {
                return '¥' + value.toLocaleString();
              }
            }
          }
        }
      }
    });
  }

  // イベント・季節要因表示
  function renderEvents() {
    const eventsData = tables[TABLE_EVENTS]?.records || [];
    const seasonData = tables[6]?.records || []; // 季節情報データ

    const now = new Date();
    const currentEvents = eventsData
      .filter(e => {
        const startDate = new Date(e.開始日時);
        const endDate = new Date(e.終了日時);
        return startDate <= now && endDate >= now && (!currentStoreId || e.店舗ID === currentStoreId);
      })
      .slice(0, 5);

    const eventsHtml = currentEvents.length > 0 ?
      currentEvents.map(event => `
        <div class="event-item">
          <div class="event-title">${event.イベント名}</div>
          <div class="event-date">${new Date(event.開始日時).toLocaleDateString()} - ${new Date(event.終了日時).toLocaleDateString()}</div>
          <span class="event-impact impact-${event.影響度?.toLowerCase() || 'low'}">${event.影響度 || '低'}</span>
        </div>
      `).join('') :
      '<div class="loading">現在進行中のイベントはありません</div>';

    container.querySelector('#events-list').innerHTML = eventsHtml;
  }

  // 在庫アラート表示
  function renderAlerts() {
    // 仮想的なアラートデータ
    const alerts = [
      { title: '商品A - 在庫不足', detail: '現在在庫: 5個 / 安全在庫: 20個', type: 'critical' },
      { title: '商品B - 在庫警告', detail: '現在在庫: 15個 / 安全在庫: 30個', type: 'warning' },
      { title: '商品C - 在庫不足', detail: '現在在庫: 2個 / 安全在庫: 15個', type: 'critical' }
    ];

    const alertsHtml = alerts.map(alert => `
      <div class="alert-item ${alert.type}" onclick="window.showScreen('scr-1778591945891')">
        <div class="alert-title">${alert.title}</div>
        <div class="alert-detail">${alert.detail}</div>
      </div>
    `).join('');

    container.querySelector('#alerts-list').innerHTML = alertsHtml;
  }

  // データ更新
  function updateDashboard() {
    updateKPIs();
    renderSalesTrend();
    renderProductRanking();
    renderOrderStatus();
    renderWeatherImpact();
    renderEvents();
    renderAlerts();
  }

  // イベントリスナー
  container.querySelector('#store-select').addEventListener('change', (e) => {
    currentStoreId = e.target.value;
    updateDashboard();
  });

  container.querySelector('#period-select').addEventListener('change', (e) => {
    currentPeriod = parseInt(e.target.value);
    updateDashboard();
  });

  container.querySelector('#btn-refresh').addEventListener('click', () => {
    updateDashboard();
  });

  // 初期化
  initStoreSelect();
  updateDashboard();
}
